// src/components/MarketCard.jsx
// Recibe prop "market" desde Dashboard (alineado con useEvents)
// Llama a /api/payments/pick/create con { eventId, tipsterId }

import React, { useState } from 'react';
import { useAuth } from '../context/AuthContext';
import './MarketCard.css';

export default function MarketCard({ market, onOpenAuth }) {
  const { user, token } = useAuth();
  const [loading,   setLoading]   = useState(false);
  const [error,     setError]     = useState('');
  const [purchased, setPurchased] = useState(market.purchased || false);

  // market shape esperado desde useEvents:
  // { id, title, type, oddsA, oddsB, tipster_id, tipster_nombre,
  //   tipster_tipo, confianza, analisis_preview, purchased }

  const tipsterBadgeColor =
    market.tipster_tipo === 'oraculo' ? '#e01a1a' :
    market.tipster_tipo === 'pro'     ? '#f5a623' : '#6b7280';

  const tipsterLabel =
    market.tipster_tipo === 'oraculo' ? '🔮 Oráculo' :
    market.tipster_tipo === 'pro'     ? '⭐ Pro'     : '👤 Novato';

  const confianzaColor =
    market.confianza >= 80 ? '#34d399' :
    market.confianza >= 60 ? '#f5a623' : '#e01a1a';

  const tieneTipster = !!market.tipster_id;

  async function handleBuyPick() {
    if (!user)         { onOpenAuth?.(); return; }
    if (purchased)     return;
    if (!tieneTipster) return;

    setLoading(true);
    setError('');

    try {
      const res = await fetch('/api/payments/pick/create', {
        method: 'POST',
        headers: {
          'Content-Type':  'application/json',
          'Authorization': `Bearer ${token}`,
        },
        body: JSON.stringify({
          eventId:   market.id,
          tipsterId: market.tipster_id,
        }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Error al crear la orden');

      // Guardar tipo y meta antes de salir a PayPal
      sessionStorage.setItem('vx_tipo_pago', 'pick');
      sessionStorage.setItem('vx_pick_meta', JSON.stringify({
        eventId:   market.id,
        tipsterId: market.tipster_id,
        evento:    market.title,
        tipster:   market.tipster_nombre,
      }));

      window.location.href = data.approvalUrl;

    } catch (err) {
      setError(err.message);
      setLoading(false);
    }
  }

  return (
    <div className="market-card card">

      {/* Header: tipster + precio */}
      {tieneTipster && (
        <div className="mc-header">
          <div className="mc-tipster">
            <div className="mc-avatar">
              {market.tipster_nombre?.[0]?.toUpperCase() || '?'}
            </div>
            <div>
              <div className="mc-tipster-name">{market.tipster_nombre}</div>
              <div
                className="mc-tipster-badge"
                style={{
                  background:  `${tipsterBadgeColor}22`,
                  color:       tipsterBadgeColor,
                  border:      `1px solid ${tipsterBadgeColor}55`,
                }}
              >
                {tipsterLabel}
              </div>
            </div>
          </div>
          <div className="mc-precio-tag">$2.00</div>
        </div>
      )}

      {/* Título del evento */}
      <div className="mc-evento">{market.title}</div>

      {/* Odds */}
      {(market.oddsA !== '—' || market.oddsB !== '—') && (
        <div className="mc-stats">
          <div className="mc-stat">
            <span className="mc-stat-label">Odds A</span>
            <span className="mc-stat-val">{market.oddsA || '—'}</span>
          </div>
          <div className="mc-stat">
            <span className="mc-stat-label">Odds B</span>
            <span className="mc-stat-val">{market.oddsB || '—'}</span>
          </div>
          {market.confianza != null && (
            <div className="mc-stat">
              <span className="mc-stat-label">Confianza</span>
              <span className="mc-stat-val" style={{ color: confianzaColor }}>
                {market.confianza}%
              </span>
            </div>
          )}
        </div>
      )}

      {/* Preview análisis */}
      {market.analisis_preview && (
        <div className={`mc-analisis ${purchased ? '' : 'mc-analisis-blurred'}`}>
          <span className="mc-analisis-label">Análisis</span>
          <p>{purchased ? market.analisis_completo || market.analisis_preview : market.analisis_preview}</p>
          {!purchased && (
            <div className="mc-blur-overlay">🔒 Desbloquea para ver el análisis completo</div>
          )}
        </div>
      )}

      {/* Error */}
      {error && <div className="mc-error">{error}</div>}

      {/* Botón compra — solo si hay tipster asignado */}
      {tieneTipster && (
        purchased ? (
          <div className="mc-purchased-badge">✅ Pick desbloqueado</div>
        ) : (
          <button
            className="mc-btn-buy"
            onClick={handleBuyPick}
            disabled={loading}
          >
            {loading ? (
              <span className="mc-btn-spinner">⚙️ Redirigiendo...</span>
            ) : (
              <>
                🎯 Comprar pick — $2.00
                <span className="mc-btn-sub">80% al Tipster · Pago seguro PayPal</span>
              </>
            )}
          </button>
        )
      )}
    </div>
  );
}
